- الله فقط مردار، خون، گوشت خوک، و آنچه را که به نام غیر الله سر بریده شده، بر شما حرام کرده است. (إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 16:115
