- این از اخبار غیب است که آن را به تو وحی می‌کنیم، و تو نزد آنان نبودی هنگامی که تصمیم می‌گرفتند. (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- آیا تعجب کردید که از جانب پروردگارتان، بر مردی از خودتان، ذکری برایتان آمد تا شما را بترساند؟ (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
