- مگر بر همسرانشان یا کنیزانی که مالک آنها هستند، که در این صورت مورد سرزنش نیستند. (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- بدین سبب که الله شب را در روز داخل می‌کند و روز را در شب داخل می‌کند. (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
