- گفت: «من از او بهترم، مرا از آتش آفریدی و او را از گل آفریدی.» (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
