- و بر آنان اندوه مخور و از آنچه نیرنگ می‌کنند، در تنگنا مباش. (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- و اگر الله گزندی به تو برساند، هیچ کس جز او نمی‌تواند آن را برطرف کند، و اگر. (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- پیش از آنان اقوام و نسلی که در خانه‌هایشان راه می‌رفتند، در این (امر) برای صاحبان خرد نشانه‌هایی است. (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- و بر دلهایشان پرده‌ها نهادیم تا آن را نفهمند، و در گوشهایشان سنگینی، و اگر. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- پیامبرانشان با دلایل روشن نزدشان آمدند، اما الله بر آن نبود که به آنها ستم کند، بلکه آنها خود بر خویشتن ستم می‌کردند. (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- و در زمین، و برای شما غیر از الله هیچ سرپرست و یاوری نیست. (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- سپس به سوی دانای نهان و آشکار بازگردانیده می‌شوید، پس شما را به آنچه انجام می‌دادید آگاه می‌کند. (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- شب را تا در آن بیاسایید، و روز را تا بینا باشید، به راستی در این (امر) برای مردمی که می‌اندیشند، نشانه‌هایی است. (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- و آنچه از جانب پروردگارت به تو نازل شده، طغیان و کفر بسیاری از آنان را افزایش می‌دهد. (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- گفت: «ای قوم من! به من خبر دهید اگر من از جانب پروردگارم بر دلیل روشنی باشم و او به من (رحمتی) داده باشد.» (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
- و می‌گویند: «چرا معجزه‌ای از پروردگارش بر او نازل نشده؟» بگو: «به راستی.» (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
- پیش از آنکه روزی فرا رسد که از سوی الله هیچ بازگشتی برای آن نیست. (مِن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ) 30:43; 42:47
- این فضل الله است که به هر کس بخواهد می‌دهد، و الله صاحب فضل عظیم است. (ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 62:4
- و به راستی در چهارپایان برای شما عبرتی است، از آنچه در شکمهایشان است به شما می‌نوشانیم. (وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ) 16:66; 23:21
- که آن حق است از جانب پروردگارشان، و الله از آنچه می‌کنند غافل نیست. (أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ) 2:144; 2:149
- از پیش رویشان و از پشت سرشان (که) جز الله را نپرستید. (مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ) 41:14; 46:21
- به راستی که شما از روی شهوت به جای زنان به مردان روی می‌آورید، بلکه شما قومی متجاوزید. (إِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَاءِ بَلْ أَنتُمْ قَوْمٌ) 7:81; 27:55
- در آنجا جاودانه می‌مانند، تا آسمانها و زمین برپاست، مگر آنچه پروردگارت بخواهد. (خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ) 11:107; 11:108
- هر که در آسمانها و هر که در زمین است، مگر آنکه الله بخواهد. (مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ) 27:87; 39:68
- در آنجا با دستبندهایی از طلا و مروارید آراسته می‌شوند، و لباسشان در آنجا پرنیان است. (يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ) 22:23; 35:33
- و از آسمان آبی فرود آورد و به آن از میوه‌ها روزی برایتان بیرون آورد. (وَأنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَّكُمْ) 2:22; 14:32
- و (به یاد آورید) هنگامی را که از شما پیمان گرفتیم و کوه طور را بالای سرتان برافراشتیم (و گفتیم): «آنچه را به شما داده‌ایم با قوت بگیرید.» (وَإِذْ أَخَذْنَا مِيثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ) 2:63; 2:93
- پس از آنها روی گرداند و گفت: «ای قوم من! به راستی که پیام پروردگارم را به شما رساندم و برایتان خیرخواهی کردم.» (فَتَوَلَّى عَنْهُمْ وَقَالَ يَاقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّي وَنَصَحْتُ لَكُمْ) 7:79; 7:93
- از زیرشان نهرها جاری است، در آنجا با دستبندهایی از طلا آراسته می‌شوند. (تَجْرِي مِن تَحْتِهِمُ الْأَنْهَارُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ) 18:31; 22:23
- اگر تمام آنچه در زمین است و مانند آن را داشته باشند تا (خود را) با آن بازخرید کنند. (لَوْ أَنَّ لَهُم مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا) 5:36; 13:18
- هیچ جنبنده‌ای نیست مگر اینکه آنان را تا سرآمدی معین به تأخیر می‌اندازد، و چون اجلشان فرا رسد. (مِن دَابَّةٍ وَلَكِن يُؤَخِّرُهُمْ إِلَى أَجَلٍ مُّسَمًّى فَإِذَا جَاءَ أَجَلُهُمْ) 16:61; 35:45
- شما را از خاک آفریدیم، سپس از نطفه، سپس از علقه، سپس. (خَلَقْنَاكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ) 22:5; 40:67
- پس الله در روز قیامت میانشان درباره آنچه اختلاف می‌کردند، داوری می‌کند. (فَاللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 22:69
- از علم (چیزی) به تو رسیده است، و از سوی الله هیچ سرپرستی و نه. (جَاءَكَ مِنَ الْعِلْمِ مَا لَكَ مِنَ اللَّهِ مِن وَلِيٍّ وَلَا) 2:120; 13:37
- و چون به انسان نعمت دهیم، روی برمی‌تابد و دوری می‌گزیند، و چون شرّی به او رسد. (وَإِذَا أَنْعَمْنَا عَلَى الْإِنسَانِ أَعْرَضَ وَنَأَى بِجَانِبِهِ وَإِذَا مَسَّهُ الشَّرُّ) 17:83; 41:51
- و هیچ کوچکتر و بزرگتری از آن نیست مگر اینکه در کتابی روشن (ثبت) است. (وَلَا أَصْغَرَ مِن ذَلِكَ وَلَا أَكْبَرَ إِلَّا فِي كِتَابٍ مُّبِينٍ) 10:61; 34:3

