- و هنگامی که الله اراده امری کند، فقط به آن می‌گوید: «شو» پس می‌شود. (وَإِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 2:117; 3:47; 19:35; 40:68
- و برای شما غیر از الله هیچ سرپرست و یاوری نیست. (وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 9:116; 29:22; 42:31
- البته گناهانشان را می‌بخشم و آنها را به باغ‌هایی که از زیرشان نهرها جاری است، درمی‌آورم. (لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 3:195; 5:12; 64:9; 66:8
- آنها را به باغ‌هایی که از زیرشان نهرها جاری است، در می‌آوریم، در آنجا جاودانه می‌مانند. (سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 64:9; 65:11
- پروردگارت بهتر می‌داند چه کسی از راهش گمراه شده، و او بهتر می‌داند. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 16:125; 53:30; 68:7
- به سوی دانای نهان و آشکار بازگردانیده می‌شوید، پس شما را به آنچه انجام می‌دادید آگاه می‌کند. (تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 9:105; 62:8
- پسرانتان را می‌کشتند و زنانتان را زنده نگه می‌داشتند، و در این (امر) برای شما از جانب پروردگارتان آزمایشی بزرگ بود. (أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ) 2:49; 7:141; 14:6
- به راستی پروردگارت بهتر می‌داند چه کسی از راهش گمراه می‌شود، و او. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 16:125; 53:30; 68:7
- الله، آنکه آنچه در آسمانها و آنچه در زمین است از آن اوست. (اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 14:2; 34:1; 42:53
- در میان امت‌هایی که پیش از شما بودند، از جن و انس. (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- الله را بپرستید، شما را جز او خدایی نیست، آیا نمی‌ترسید؟ (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
- و بر دلهایشان پرده‌ها نهادیم تا آن را نفهمند، و در گوشهایشان سنگینی. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- در روز قیامت میانشان درباره آنچه اختلاف می‌کردند، داوری می‌کند. (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- گفت: «ای قوم من! به من خبر دهید اگر من از جانب پروردگارم بر دلیل روشنی باشم.» (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- این (کیفر) به خاطر آن چیزی است که دستهایتان پیش فرستاده، و الله به بندگان ستمگر نیست. (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- در دنیا برایشان خواری و در آخرت عذابی بزرگ است. (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- آنچه در آسمانها و آنچه در زمین است، و الله کارساز (بندگان) بسنده است. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- مگر کسانی که ایمان آوردند و کارهای شایسته کردند، که برایشان پاداشی بی‌منت است. (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- تا آنچه را که بدان علم نداری، با من شریک قرار دهی، پس از آن دو اطاعت مکن. (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- به راستی این (قرآن) تذکری است، پس هر که بخواهد راهی به سوی پروردگارش برمی‌گزیند. (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- و هر که شکر کند، تنها به سود خویش شکر می‌کند، و هر که ناسپاسی کند. (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- کسانی که نماز را برپا می‌دارند و زکات می‌دهند و به آخرت یقین دارند. (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- (ایمان آوردیم) به ابراهیم، اسماعیل، اسحاق، یعقوب و اسباط، و آنچه به موسی و عیسی داده شد. (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- گروه گروه، تا چون به آنجا رسند، درهایش گشوده شود و نگهبانانش به ایشان گویند. (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- الله شما را به لغو در سوگندهایتان مؤاخذه نمی‌کند، ولی شما را به آنچه (دلها) کسب کرده‌اند مؤاخذه می‌کند. (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- رحمتی، که بدان شاد می‌شوند، و اگر به سبب آنچه دستهایشان پیش فرستاده، گزندی به ایشان رسد. (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- باغ‌هایی که از زیرشان نهرها جاری است، در آنها جاودانه می‌مانند، و چه نیکوست پاداش عمل‌کنندگان! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- الله می‌داند آنچه را در آسمانها و آنچه را در زمین است، و الله. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- از الله اطاعت کنید و از رسول اطاعت کنید، پس اگر رویگردان شوید، بر او (رسول) فقط (رساندن پیام) است. (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- برای آنها پاداششان نزد پروردگارشان است، و نه ترسی بر آنهاست و نه. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- و گفتند: «آیا زمانی که ما استخوان‌هایی پوسیده و خاک شدیم، آیا به آفرینشی جدید برانگیخته می‌شویم؟» (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- و جز الله برای خود هیچ سرپرست و یاوری نمی‌یابند. (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- «چه مدت درنگ کردی؟» گفت: «یک روز یا پاره‌ای از روز را درنگ کردم.» گفت. (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- تا روز قیامت، آیا جز الله خدایی هست که (آذوقه) برایتان بیاورد؟ (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- هر که کار شایسته کند، از مرد یا زن، در حالی که مؤمن باشد. (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- کسانی که از راه الله بازمی‌دارند و آن را کج می‌خواهند، و به آخرت (ایمان ندارند). (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- از هر جا که خواستید (بخورید) و به این درخت نزدیک نشوید که از ستمکاران خواهید شد. (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- بگو: «ای قوم من! بر جایگاه خود عمل کنید، من نیز عمل می‌کنم، پس به زودی خواهید دانست.» (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- به راستی زیانکاران کسانی هستند که در روز قیامت، خود و خانواده‌شان را زیان کرده‌اند، هشدار. (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- هر که راه یابد، به سود خود راه می‌یابد، و هر که گمراه شود، به زیان خود گمراه می‌شود، و. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- و کسانی که کفر ورزیدند می‌گویند: «چرا معجزه‌ای از پروردگارش بر او نازل نشد؟» (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- آنکه شب را برایتان قرار داد تا در آن آرام گیرید، و روز را روشن (قرار داد)، به راستی. (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- پیش از آنکه روزی فرا رسد که در آن نه داد و ستدی است و نه. (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- تا بیندیشند که در همراهش جنونی نیست، او فقط هشداردهنده‌ای آشکار است. (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- در آنجا جاودانه می‌مانند، عذاب از آنها تخفیف نمی‌شود و به آنها مهلت داده نمی‌شود. (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- چشمانت را به آنچه گروهی از ایشان را از آن برخوردار کرده‌ایم، مگشای. (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- و از مردم در کالاهایشان نکاهید، و در زمین فساد مکنید. (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- و سلام بر او روزی که زاده شد، و روزی که می‌میرد، و روزی که زنده برانگیخته می‌شود. (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- ای قوم من! بر جایگاه خود عمل کنید، من نیز عمل می‌کنم، پس به زودی خواهید دانست که. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- و هیچ پیامبری را نرسد که جز به اذن الله معجزه‌ای بیاورد. (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- سپس هر کسی به تمام آنچه کرده است، پاداش داده می‌شود، و به آنها ستم نخواهد شد. (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- هر کس از مرد یا زن، در حالی که مؤمن باشد، پس آنان داخل بهشت می‌شوند. (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- فرزندی نگرفته و در حکومت، شریکی ندارد. (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- و هر که را الله هدایت کند، او هدایت‌یافته است، و هر که را گمراه کند، هرگز برای او. (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
