- مگر پس از آنکه علم به آنها رسید، از روی حسادت میانشان. (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- نماز را برپا می‌دارند و از آنچه روزی‌شان داده‌ایم، پنهان و آشکار انفاق می‌کنند. (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- آیا غیر از الله چیزی را بخوانیم که نه سودمان می‌دهد و نه زیانمان؟ (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- به آنچه بر تو نازل شده و آنچه پیش از تو نازل شده، ایمان می‌آورند. (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- آیا ندیدی که الله از آسمان آبی فرود آورده است؟ (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- چون کاری را اراده کند، فقط به آن می‌گوید: باش، پس می‌شود. (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- و به سوی مدین برادرشان شعیب را (فرستادیم). گفت: ای قوم من، الله را بپرستید. (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- این از اخبار غیب است که به تو وحی می‌کنیم؛ تو این را نمی‌دانستی. (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- و هنگامی که اجلشان فرا رسد، نه ساعتی تأخیر می‌کنند و نه پیشی می‌گیرند. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- و از گام‌های شیطان پیروی نکنید، که او برای شما دشمنی آشکار است. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- و از مردم کسانی هستند که درباره الله بدون هیچ علمی جدال می‌کنند. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- الله آن را به هر که بخواهد می‌دهد، و الله صاحب فضل عظیم است. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- هر کسی به تمامی آنچه کرده است، پاداش داده می‌شود و به آنها ستم نمی‌شود. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- و نفسی را که الله حرام کرده است، به ناحق مکشید. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- چون کاری را اراده کند، فقط به آن می‌گوید: باش. (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- از درهای جهنم درآیید، در آن جاودان باشید، و چه بد است جایگاه متکبران! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- آیا ندیدی کسانی را که بهره‌ای از کتاب به آنها داده شد؟ (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- برای آنها بهشت‌هایی است که از زیر آنها نهرها جاری است، در آنجا جاودانند. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- ای قوم من، به توانایی خود عمل کنید، من نیز عمل می‌کنم، پس به زودی خواهید دانست. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- هر کس با الله و پیامبرش مخالفت کند، آتش جهنم برای اوست و در آن جاودان است. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- بر دلهایشان پرده‌ها نهادیم تا آن را نفهمند، و در گوشهایشان سنگینی. (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- و در هیچ آبادی بیم‌دهنده‌ای نفرستادیم مگر اینکه خوشگذرانانش گفتند: ما. (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- گفتند: از پروردگارت بخواه تا برای ما روشن کند که آن چگونه است. (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- خواهند گفت: الله. بگو: ستایش مخصوص الله است، ولی بیشترشان. (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- و پاسخ قومش جز این نبود که گفتند: آنان را بیرون کنید. (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- نهرها از زیر آنها جاری است، در آنجا جاودانند، این است رستگاری بزرگ. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- اینان بر هدایتی از پروردگارشان هستند و اینان رستگارانند. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- کسی که عذاب خوارکننده به او رسد و عذاب پایدار بر او فرود آید. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- در زمین بگردید و بنگرید که سرانجام تکذیب‌کنندگان چگونه بود. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- هرگز آن را آرزو نمی‌کنند به سبب آنچه دست‌هایشان پیش فرستاده، و الله به ستمکاران داناست. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- او داناتر است به کسی که از راهش گمراه شده، و او داناتر است. (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- به‌درستی که الله پروردگار من و پروردگار شماست، پس او را بپرستید، این است راه راست. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- او بر مردم فضل دارد، اما بیشترشان سپاس نمی‌گزارند. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- آسمان‌ها و زمین و آنچه را میان آنهاست، جز به حق و برای مدتی معین نیافریدیم. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- آنها را واگذار تا به باطل خود فرو روند و بازی کنند تا روزی را که به آنها وعده داده شده، ملاقات کنند. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- و چون با مؤمنان دیدار کنند، گویند: ایمان آوردیم، و چون با یکدیگر خلوت کنند. (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- تورات و انجیل و آنچه را از پروردگارشان برایشان نازل شده، برپا می‌دارند. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- آنچه را پیش رویشان و پشت سرشان است می‌داند، و آنها به آن احاطه ندارند. (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- و او کسی است که آسمان‌ها و زمین را در شش روز آفرید. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- به‌درستی که در این برای شما نشانه‌ای است، اگر مؤمن هستید. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- و چه چیز مردم را بازداشت از اینکه ایمان بیاورند، چون هدایت برایشان آمد؟ (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- و برای الله شریکانی قرار دادند تا از راهش گمراه کنند. بگو: بهره‌مند شوید. (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- و شگفت زده شدند که از میان خودشان بیم‌دهنده‌ای برایشان آمد، و کافران گفتند: این. (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- به‌درستی که پروردگارت داناتر است به کسی که از راهش گمراه شده است. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- مانند کسی که مال خود را برای ریا به مردم انفاق می‌کند و به الله ایمان نمی‌آورد. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- از آنچه روزی شما کرده‌ایم، پیش از آنکه فرا رسد، انفاق کنید. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- آنچه را در آسمان‌ها و آنچه را در زمین است، برای شما مسخر کرد. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- و ما در آنچه ما را به آن می‌خوانید، در شک و تردیدیم. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- به‌درستی که پروردگارت روزی را برای هر که بخواهد گشاده می‌دارد و تنگ می‌گرداند. به‌درستی که او. (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- پروردگار آسمان‌ها و زمین و آنچه میان آنهاست، اگر شما یقین دارید. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- به الله ایمان آوردیم و به آنچه بر ما نازل شده و آنچه بر. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- و کسانی که ستم کردند، صدای مهیب آنان را فرو گرفت و در خانه‌هایشان به رو افتاده، مرده بودند. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- پس بر شما گناهی نیست در آنچه آنها درباره خود انجام می‌دهند. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- پروردگارت داناتر است به کسی که از راهش گمراه شده، و او. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- با روح (وحی) به فرمان خود، بر هر کس از بندگانش که بخواهد. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- و به عیسی پسر مریم نشانه‌های روشن دادیم و او را با روح القدس تأیید کردیم. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- تا در روز قیامت میانشان در آنچه اختلاف می‌کردند، داوری کند. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- و بالای آن را زیر آن گردانیدیم و بر آن سنگ‌هایی از گل پخته باریدیم. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- چه آنان را بیم دهی یا بیم ندهی، برایشان یکسان است، ایمان نمی‌آورند. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- غیر از مردم، پس آرزوی مرگ کنید اگر راستگویید. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- الله، برای شما معبودی جز او نیست. آیا پروا نمی‌کنید؟ (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- یا بعضی از آنچه به آنان وعده می‌دهیم، به تو نشان دهیم، یا تو را بمیرانیم، پس بازگشتشان به سوی ماست. (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- گفتند: آیا هنگامی که مردیم و خاک و استخوان شدیم، آیا برانگیخته خواهیم شد؟ (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- به‌درستی که فضل در دست الله است، به هر کس بخواهد می‌دهد، و الله. (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- و به سوی دانای نهان و آشکار بازگردانده می‌شوید، پس شما را به آنچه می‌کردید، آگاه می‌گرداند. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- ای کسانی که ایمان آوردید، نعمت الله را بر خود یاد کنید، آنگاه که. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- و پیش از تو جز مردانی که به آنها وحی می‌کردیم، نفرستادیم. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- گناهانش را می‌بخشاید و او را به بهشت‌هایی درآرد که از زیر آنها نهرها جاری است. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- هر کس بیمار است یا در سفر، پس به شماره روزهای دیگر. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- آنها جز از گمان پیروی نمی‌کنند و جز به تخمین نمی‌پردازند. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- برای کسی که به الله و روز بازپسین امید دارد، سرمشقی نیکوست. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- و آسمان‌ها و زمین و آنچه را میان آنهاست، جز به حق نیافریدیم. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- دستت را در گریبانت ببر، سفید و بی‌عیب بیرون آید. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- به رحمت خود، هر که را بخواهد، اختصاص می‌دهد و الله صاحب فضل عظیم است. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- آیا ندانستی که الله راست فرمانروایی آسمان‌ها و زمین؟ (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- و هر کار خیری که برای خود پیش می‌فرستید، آن را نزد الله خواهید یافت. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- و از هر جا بیرون رفتی، روی خود را به سوی مسجد الحرام کن. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- پیش از شما (کسانی) بوده‌اند و هرگز برای سنت الله تبدیلی نخواهی یافت. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- کسی که از آن اوست آنچه در آسمان‌ها و آنچه در زمین است. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- و هیچ ماده‌ای باردار نمی‌شود و نمی‌زاید مگر به علم او. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- شب را مسخر کرد و خورشید و ماه را، هر یک تا مدتی معین روانند. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- نهرها از زیر آنها جاری است، در آنجا جاودانند و این است پاداش. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- گفت: نه، بلکه نفس‌هایتان کاری را برایتان آراسته، پس صبری جمیل. (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- آنچه در آسمان‌ها و آنچه در زمین است، و اینکه الله. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- و هیچ پیامبری برایشان نیامد مگر اینکه او را ریشخند می‌کردند. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- گفتند: ای موسی، یا تو بینداز یا ما بیندازیم؟ (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- اوست که شما را می‌میراند و برخی از شما را به پست‌ترین عمر بازمی‌گرداند، تا. (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- برایشان بهشت‌هایی است که از زیر آنها نهرها جاری است، در آنجا جاودانند. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- و بر دلهایشان پرده‌ها نهادیم تا آن را نفهمند و در گوشهایشان سنگینی. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- به‌درستی که وعده الله حق است، ولی بیشترشان نمی‌دانند. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- این به سبب آن است که با الله و پیامبرش مخالفت کردند، و هر کس با الله مخالفت کند. (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- و روزی که آنها را ندا دهد و گوید: کجایند شریکان من که می‌پنداشتید؟ (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- آیا ندیدند که الله، آن کس که آسمان‌ها و زمین را آفرید، می‌تواند مانند آنها را بیافریند؟ (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- آن کس که شما را از خاک آفرید، سپس از نطفه، سپس. (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- می‌گفتند: پروردگارا، چرا پیامبری به سوی ما نفرستادی تا از آیاتت پیروی کنیم؟ (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- سپس بازگشتشان به سوی پروردگارشان است، و آنها را به آنچه می‌کردند، آگاه می‌سازد. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- آنها را به آن هیچ علمی نیست، آنان جز از گمان پیروی نمی‌کنند. (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- ما پدران خود را بر آیینی یافته‌ایم و ما بر آثارشان رهرویم. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- کسانی که کتاب به آنها داده شد، اختلاف نکردند مگر پس از آنکه علم برایشان آمد. (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- و چون ابراهیم گفت: پروردگارا، این شهر را امن گردان. (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- و برای شما گوش و چشم‌ها و دل‌ها قرار داد، چه اندک سپاس می‌گزارید! (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- کسانی که درباره آیات الله بدون حجتی که برایشان آمده، جدال می‌کنند. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- پس از آیین ابراهیم، که حق‌گرا بود، پیروی کنید و او از مشرکان نبود. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- و چون شما را از فرعونیان رهایی بخشیدیم، که شما را به بدترین عذاب می‌آزردند. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- این است دین استوار، ولی بیشتر مردم نمی‌دانند. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- آیا ندیدی که الله آنچه را در. است، برای شما مسخر کرده است؟ (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- کافران خواهند گفت: این جز سحری آشکار نیست. (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- و چون آیات روشن ما بر آنان خوانده شود، کافران می‌گویند. (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- بهشت‌های جاویدان که از زیر آنها نهرها جاری است، در آنجا جاودانند. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- هر چه بخواهد (می‌آفریند)، به‌درستی که الله بر هر چیزی تواناست. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- تا گناهانتان را بیامرزد و شما را تا مدتی معین مهلت دهد. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- آیا می‌خواهید ما را از آنچه پدرانمان می‌پرستیدند، بازدارید؟ (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- و چون پروردگارت به فرشتگان گفت: من بشری از گِل می‌آفرینم. (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- و اوست که بادها را پیشاپیش رحمت خود، بشارت‌دهنده می‌فرستد. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- بگو: در زمین بگردید و بنگرید که سرانجام چگونه بود. (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- به‌درستی که در آفرینش آسمان‌ها و زمین و آمدوشد شب و روز (نشانه‌هایی است). (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- کیست که به الله قرض الحسنه دهد تا آن را چندین برابر برایش کند؟ (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- پس میانشان به آنچه الله نازل کرده حکم کن و از هوس‌هایشان پیروی مکن. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- آیا جز این انتظار دارند که فرشتگان به سویشان بیایند یا فرمان پروردگارت بیاید؟ (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- به‌درستی کسانی که بر الله دروغ می‌بندند، رستگار نمی‌شوند. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- همانند عادت فرعونیان و کسانی که پیش از آنان بودند، که آیات ما را تکذیب کردند. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- و مؤمنانی را که کارهای شایسته می‌کنند، مژده می‌دهد که آنان را پاداشی است. (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- الله روزی را برای هر که از بندگانش بخواهد گشاده می‌دارد و تنگ می‌گرداند. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- و به سوی دانای نهان و آشکار بازگردانده می‌شوید، پس شما را به آنچه می‌کردید، آگاه می‌گرداند. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- و خویشاوندان، بعضی به بعضی دیگر در کتاب الله اولی‌ترند. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — فرض / واجب (انجام آن لازم است؛ ترک آن گناه است)
- mustahabb / mandub (مستحب / مندوب) — مستحب / مندوب (انجام آن ثواب دارد، ترک آن گناه ندارد)
- mubah (مباح) — مباح / اجازه داده شده (نه ثواب دارد و نه گناه)
- makruh (مكروه) — مکروه (ناخوشایند، انجامش بی‌اشکال است اما ترکش بهتر است)
- haram (حرام) — حرام (انجام آن گناه است)
- halal (حلال، حلال / شرعی) — هم مباح و هم مستحب را در بر می‌گیرد — هر چیزی که حرام نباشد
- فقط الله را عبادت کنید و از او یاری/کمک بخواهید. 1:5
- فقط الله را عبادت کنید. 2:21
- برای الله هیچ شریکی قرار ندهید. 2:22
- الله است که می‌بخشد (توبه را می‌پذیرد)، توبه آدم (علیه السلام) را پذیرفت. 2:37
- حق را با باطل نیامیزید و حق را پنهان نکنید. 2:42
- نماز (نمازهای روزانه) را برپا دارید و زکات (صدقه) بدهید. 2:43
- دیگران را به نیکی فرمان دهید پس از آنکه خود آن را به کار بستید. 2:44
- در همه امور خود از الله یاری بجویید. 2:45
- دست به فساد نزنید و آن را گسترش ندهید. 2:60
- مردم را از رفتن به عبادتگاه‌ها باز ندارید. 2:114
- حرمت مسجد را پاس دارید. مکان‌های نماز خود را پاک و پاکیزه نگه دارید. 2:125
- الله را یاد کنید (با نماز، تسبیح و غیره) و او شما را یاد می‌کند، و از او سپاسگزار باشید. 2:152
- در سختی‌ها شکیبایی پیشه کنید. 2:153
- از گام‌های شیطان پیروی نکنید که دشمن آشکار شماست. 2:168
- از هیچ کس کورکورانه پیروی نکنید. 2:170
- همه امانت‌ها را نگه دارید و به جای آورید. واجبات دینی خود را با اخلاص انجام دهید. سوگندها و پیمان‌های خود را وفا کنید. وعده‌ها را به ویژه آنچه به الله داده‌اید، حفظ کنید. نیازمندان را یاری کنید و سختی‌ها را آسان سازید. از گناهانی که به از دست دادن لطف الهی می‌انجامد، پرهیز کنید. نگذارید تکبر شما را به ستم بکشاند. 2:177
- در قصاص (قانون برابری در مجازات) برای شما زندگی است. 2:179
- در ماه رمضان روزه بگیرید. روزه مقرر را به جای آورید تا پرهیزگار شوید. 2:183
- به قرآن به عنوان منبع نهایی هدایت احترام بگذارید. 2:185
- اموال یکدیگر را به ناحق مخورید و به حاکمان (پیش از طرح دعاوی خود) رشوه ندهید. 2:188
- دیگران را به گفتار یا کردار ستم مکنید. هرگز به عنوان متجاوز جنگ نکنید، بلکه فقط در دفاع. 2:190
- از یتیمان حمایت کنید. در مورد یتیمان، در اموال آنان به درستی عمل کنید و اموالشان را مخورید. 2:220
- توبه کنید و از الله آمرزش بخواهید. در دوران قاعدگی رابطه جنسی نداشته باشید. پاکی (هم جسمانی و هم روحانی) را حفظ کنید. 2:222
- مسئولیت‌های خود را در قبال خانواده انجام دهید. 2:233
- رهبران را بر اساس شایستگی انتخاب کنید. 2:247
- در دین اجباری نیست. 2:256
- دارایی خود را در راه خیر انفاق کنید. در مال و زمان سخاوتمند باشید. 2:261
- صدقه خود را با منت‌گذاری و خودستایی باطل نکنید. 2:264
- شیطان شما را به فقر می‌ترساند و به فحشا (کارهای زشت، روابط جنسی نامشروع، گناهان) فرمان می‌دهد. 2:268
- نیازمندان را جستجو کنید و به آنان کمک کنید. 2:273
- با ربا و سود سر و کار نداشته باشید. مال ربوی مخورید. ربا مخورید. 2:275
- اگر بدهکار در تنگنا است، به او مهلت دهید. 2:280
- در معاملات تجاری به عهد خود وفا کنید. در امور مالی خود راستگو باشید. در همه تعهدات خود با درستی رفتار کنید. هنگامی که به مدت معین بدهکاری نوشتید، آن را بنویسید. هر گاه قرارداد تجاری بستید، گواه بگیرید. 2:282
- همه امانت‌ها را نگه دارید و به جای آورید. 2:283
- به کتاب‌های نازل شده و همه پیامبران ایمان آورید. 2:285
- الله هیچ کس را بیش از توانایی‌اش تکلیف نمی‌کند. آنچه از خوبی به دست آورند، پاداش آن را می‌گیرند و آنچه از بدی به دست آورند، کیفر آن را می‌بینند. خداوند کسی را بیش از ظرفیتش تکلیف نمی‌کند؛ ما نیز نباید چنین کنیم. در سختی‌ها به تدبیر الله توکل کنید. 2:286
- هر که پیمان‌ها را وفا کند و از الله بسیار بترسد، الله پرهیزگاران را دوست دارد. 3:76
- اگر توانایی دارید، حج به جای آورید. 3:97
- پراکنده نشوید. 3:103
- به نیکی فرمان دهید و از بدی بازدارید. در جامعه خود به عدالت تشویق کنید. دیگران را به یاد الله دعوت کنید. 3:104
- مؤمنان باید بر الله توکل کنند. 3:122
- ربا مخورید. 3:130
- از الله و پیامبرش اطاعت کنید تا مشمول رحمت شوید. 3:132
- الله کسانی را دوست دارد که در خوشی و ناخوشی (در راه الله - کارهای خیر، صدقات و غیره) انفاق می‌کنند، خشم خود را فرو می‌برند و از مردم درمی‌گذرند. 3:134
- خشم خود را فرو برید. بر خشم خود مسلط باشید. 3:134
- خطاهای دیگران را ببخشید و درگذرید. 3:135
- در گفتار درشت‌خو نباشید. با کسانی که با شما مخالفند، شکیبایی کنید. 3:159
- اگر الله شما را یاری کند، هیچ کس بر شما چیره نمی‌شود؛ و اگر شما را خوار کند، کیست که پس از او شما را یاری کند؟ 3:160
- هر کسی مرگ را خواهد چشید. و تنها در روز قیامت پاداش خود را به تمامی خواهید گرفت. 3:185
- درباره شگفتی‌های طبیعت و آفرینش این جهان، عمیقاً بیندیشید. بدانید که خداوند جهان را با معنا و هدف آفریده است. 3:191
- مردان و زنان برای کارهای خود پاداشی برابر دارند. 3:195
- برای کسانی که از پروردگار خود می‌ترسند، باغ‌هایی (در بهشت) است که از زیر آنها نهرها جاری است؛ در آنجا جاودانه خواهند ماند، که از جانب الله پذیرایی است. 3:198
- در هر کاری همواره خشنودی الله را بجویید. 3:200
- از پروردگار خود پروا کنید، از او بترسید و (پیوندهای) خویشاوندی را مبرید. 4:1
- اموال یتیمان را به آنان بدهید و (مال بد خود را) با (مال خوب آنان) عوض نکنید؛ و اموال آنان را (به اموال خود) نیفزایید و مخورید. 4:2
- به زنان (که با آنان ازدواج می‌کنید) مهریه‌شان را (هدیه زناشویی که شوهر در هنگام ازدواج به همسر خود می‌دهد) با خوش‌دلی بدهید. 4:4
- حقوق یتیمان را حفظ کنید. 4:6
- دارایی مرده باید میان اعضای خانواده‌اش تقسیم شود. زنان حق ارث دارند. 4:7
- اموال یتیمان را به ناحق مخورید. 4:10
- از دستورات مربوط به ارث اطاعت کنید. 4:11
- ارث بردن زنان بر خلاف میلشان جایز نیست و با آنان به سختی رفتار نکنید. با آنان (همسران) به نیکی زندگی کنید. حقوق زنان را محترم شمارید و رعایت کنید. با همسر خود با مهربانی و شفقت رفتار کنید. با زنان با عزت و عدالت رفتار کنید. 4:19
- با کسانی که با شما نسبتی دارند، ازدواج نکنید. 4:23
- خود (یا یکدیگر) را نکشید. بی‌گمان الله با شما مهربان است. اموال یکدیگر را به ناحق مخورید. 4:29
- اگر از گناهان بزرگی که از آنها نهی شده‌اید، دوری کنید، الله گناهان (کوچک) شما را می‌بخشاید و شما را به جایگاه ارجمندی (بهشت) درآورد. 4:31
- آنچه را که الله به برخی از شما بر برخی دیگر برتری داده، آرزو مکنید. از حسد و رشک بپرهیزید. 4:32
- مردان سرپرست و نگهبان زنانند، زیرا الله برخی را بر برخی برتری داده و به سبب آنکه از اموال خود (برای آنان) هزینه می‌کنند. مرد سرپرست و پشتیبان خانواده است. 4:34
- الله را بپرستید و هیچ چیز را با او شریک نکنید، به پدر و مادر، خویشاوندان، یتیمان، مستمندان، همسایه، همنشین، در راه ماندگان (که برخورد می‌کنید) و بردگانتان نیکی کنید. الله کسانی را که متکبر و فخر فروش هستند، دوست ندارد. به دیگران نیکی کنید. به ناتوانان رحم کنید. پیوندهای خویشاوندی را نگه دارید و به خویشاوندان احترام کنید. 4:36
- بخیل نباشید. 4:37
- الله شرک را نمی‌بخشاید، ولی غیر از آن را برای هر که بخواهد می‌بخشاید. 4:48
- به دیگران رشک مبرید. 4:54
- الله به شما فرمان می‌دهد که امانت‌ها را به صاحبانشان بازگردانید و هنگامی که میان مردم داوری می‌کنید، به عدالت داوری کنید. 4:58
- از الله و پیامبرش اطاعت کنید. از صاحبان امر (حاکمان) خود اطاعت کنید. 4:59
- به ناتوانان و آسیب‌پذیران ستم مکنید. 4:75
- هر خوبی که به شما می‌رسد، از جانب الله است؛ و هر بدی که به شما می‌رسد، از خود شماست. 4:79
- هر که از پیامبر (محمد ﷺ) اطاعت کند، در حقیقت از الله اطاعت کرده است. 4:80
- هر که برای کار نیک شفاعت کند، پاداشی از آن خواهد داشت؛ و هر که برای کار بد شفاعت کند، سهمی از بار آن خواهد داشت. 4:85
- هیچ مؤمنی حق ندارد مؤمن دیگری را بکشد، مگر به خطا. 4:92
- هر که مؤمنی را به عمد بکشد، کیفر او دوزخ است که در آن جاودانه خواهد ماند. خشم و لعنت الله بر اوست و عذابی بزرگ برای او آماده شده است. 4:93
- هر که در راه الله (از خانه خود) هجرت کند، در زمین جایگاه‌های بسیار و گشایش فراوان خواهد یافت. 4:100
- در نمازهای خود دقیق باشید. 4:103
- کسانی را که به امانت‌ها خیانت می‌کنند، حمایت یا وکالت نکنید. 4:105
- از الله آمرزش بخواهید، بی‌گمان الله آمرزنده مهربان است. 4:106
- ای کسانی که ایمان آورده‌اید! به عدالت قیام کنید و برای الله شهادت دهید، هر چند به زیان خودتان، یا پدر و مادر، یا خویشاوندانتان باشد، خواه توانگر باشند یا تنگدست. عدالت را به تأخیر نیندازید؛ برای اصلاح خطاها فوراً اقدام کنید. 4:135
- منافقان می‌خواهند الله را فریب دهند، ولی او آنان را فریب می‌دهد. 4:142
- منافقان در پایین‌ترین درجه آتش خواهند بود؛ و هرگز یاوری برای آنان نخواهی یافت. 4:145
- الله دوست ندارد که بدی (در مورد کسی) آشکارا گفته شود، مگر از کسی که به او ستم شده است. 4:148
- پیامبران را به عنوان بشارت‌دهندگان و هشداردهندگان فرستادیم، تا پس از (آمدن) پیامبران، مردم را بر الله حجتی نباشد. 4:165
- به پیمان‌ها و وعده‌های خود وفا کنید. 5:1
- در نیکی و پرهیزگاری با یکدیگر همکاری کنید، و در گناه و دشمنی همکاری نکنید. 5:2
- مردار، خون و گوشت خوک را مخورید. 5:3
- دادگر باشید، نباید دشمنی و کینه دیگران شما را از عدالت باز دارد. دادگر باشید. بدانید که دادگری به پرهیزگاری نزدیکتر است. عدالت را به تأخیر نیندازید؛ برای اصلاح خطاها فوراً اقدام کنید. 5:8
- وسیله تقرب به الله را بجویید و در راه او چنان که شاید جهاد کنید. تا رستگار شوید. 5:35
- به سوگندها و پیمان‌های خود وفا کنید. 5:89
- از نوشیدنی‌های مست‌کننده و الکل دوری کنید. به شدت از مسکرات (همه گونه نوشیدنی‌های الکلی)، قمار، انصاب (بت‌های سنگی) و ازلام (تیرهای بخت‌آزمایی) که همه پلید از عمل شیطان است، دوری کنید. 5:90
- در حال احرام حج یا عمره، شکار نکنید. 5:95
- درباره چیزهایی که اگر برای شما روشن شود، شما را اندوهگین می‌کند، مپرسید. 5:101
- به خدایان دیگران دشنام ندهید. به آنها که (کافران) به جای الله می‌پرستند، دشنام ندهید، تا آنان نیز از روی نادانی به الله دشنام ندهند. 6:108
- اگر از اکثر کسانی که بر روی زمین هستند، پیروی کنید، شما را از راه الله گمراه می‌کنند. آنان جز از گمان پیروی نمی‌کنند و جز به دروغ سخن نمی‌گویند. 6:116
- (ای مردم) همه گناهان، آشکار و پنهان را رها کنید. 6:120
- (ای مؤمنان) از آن (گوشت) که نام الله بر آن برده نشده است (به هنگام ذبح) مخورید. 6:121
- هر که را الله بخواهد هدایت کند، سینه‌اش را برای اسلام می‌گشاید؛ و هر که را بخواهد گمراه کند، سینه‌اش را تنگ و گرفتار می‌سازد. 6:125
- در خرج کردن میانه‌رو باشید و از اسراف بپرهیزید. حقوق همه موجودات را حفظ کنید. 6:141
- برای الله شریک قائل نشوید، به پدر و مادر نیکی کنید، فرزندان خود را از بیم فقر مکشید، به کارهای زشت نزدیک نشوید، کسی را که الله کشتنش را حرام کرده، جز به حق مکشید. 6:151
- راست‌گو باشید؛ در هیچ یک از معاملات خود خیانت نکنید. به مال یتیم نزدیک نشوید، مگر به قصد اصلاح آن؛ پیمانه و ترازو را به عدالت کامل کنید؛ هرگاه سخن گفتید، راست گویید هر چند به زیان خویشاوند باشد؛ و به پیمان الله وفا کنید. 6:152
- از راه راست پیروی کنید و از راه‌های (دیگر) پیروی نکنید، که شما را از راه او پراکنده می‌سازد. 6:153
- بگو (ای محمد ﷺ): "بی‌گمان، نماز من، قربانی من، زندگی من و مرگ من، برای الله، پروردگار جهانیان است." 6:162
- تکبر نورزید. 7:13
- شیطان شما را نفریبد. 7:27
- بگو (ای محمد ﷺ): "پروردگارم به عدالت فرمان داده است…" 7:29
- در همه چیز از حدود تعیین شده الله پیروی کنید. در گفتار و کردار از حد تجاوز نکنید. بخورید و بیاشامید، اما اسراف نکنید. هنگام نماز، لباس نیکو بپوشید. 7:31
- الله آسمان‌ها و زمین را در شش روز آفرید، سپس بر عرش (به گونه‌ای شایسته جلالش) قرار گرفت. 7:54
- پروردگار خود را به زاری و پنهانی بخوانید. او از متجاوزان خوش نمی‌آید. 7:55
- در زمین پس از اصلاح آن، فساد مکنید و او را با بیم و امید بخوانید. 7:56
- و کسانی که کارهای بد کردند و پس از آن توبه کردند و ایمان آوردند، بی‌گمان پروردگارت پس از آن آمرزنده و مهربان است. 7:153
- بگو (ای محمد ﷺ): "ای مردم! من فرستاده الله به سوی همه شما هستم…" 7:158
- و (همه) نیکوترین نام‌ها از آن الله است، پس او را به آن‌ها بخوانید، و کسانی را که در نام‌های او کج‌روی می‌کنند، رها کنید… 7:180
- هر که را الله گمراه کند، هیچ راهنمایی برای او نیست؛ و آنان را در سرکشی‌شان سرگشته رها می‌کند. 7:186
- عفو را پیشه کن، به نیکی فرمان ده، و از نادانان روی بگردان (یعنی آنان را مجازات مکن). 7:199
- خطاهای دیگران را ببخشید. 7:199
- و اگر وسوسه‌ای از شیطان به تو رسد، به الله پناه ببر. او شنوای داناست. 7:200
- مؤمنان تنها کسانی هستند که چون الله یاد شود، دل‌هایشان به هراس افتد و چون آیات او بر آنان خوانده شود، ایمانشان افزون می‌گردد… 8:2
- به الله و پیامبرش خیانت مکنید و به امانت‌های خود (و همه وظایفی که الله بر عهده شما نهاده) آگاهانه خیانت نکنید. 8:27
- اگر از الله اطاعت و پروا کنید، به شما فرقان (معیاری برای تشخیص حق از باطل، یا راهی برای برون‌رفت از هر دشواری) عطا می‌کند. 8:29
- کافران اموال خود را هزینه می‌کنند تا (مردم را) از راه الله بازدارند، و پیوسته آن را هزینه می‌کنند، اما سرانجام این کار مایه حسرتشان خواهد شد. 8:36
- به کسانی که کفر ورزیدند، بگو اگر (از کفر) دست بردارند، گذشته‌هایشان بخشیده می‌شود. و اگر (به آن) بازگردند، سنت (و سرنوشت) پیشینیان (که عذاب شدند) پیشتر رفته است (به عنوان هشدار). 8:38
- هنگامی که با (نیروی دشمن) روبرو شدید، پایداری کنید و نام الله را بسیار یاد کنید (با زبان و دل)، تا رستگار شوید. 8:45
- مانند کسانی نباشید که با تکبر و برای خودنمایی از خانه‌های خود خارج شدند و (مردم را) از راه الله بازداشتند. 8:47
- الله هیچ نعمتی را که به قومی ارزانی داشته، تغییر نمی‌دهد، مگر آنکه آنچه را در خودشان است، تغییر دهند. 8:53
- بدترین جنبندگان نزد الله کافرانند. 8:55
- خداوند میان دل‌های مؤمنان، الفت و محبت برقرار می‌کند. 8:63
- کسانی را که پناه می‌خواهند، حمایت و یاری کنید. 9:6
- مشرکان را نرسد که مساجد الله را آباد کنند. 9:17
- آنان (کافران، یهودیان و مسیحیان) می‌خواهند نور الله (که با آن محمد ﷺ فرستاده شده – توحید اسلامی) را با دهان خود خاموش کنند، ولی الله جز این نمی‌خواهد که نور خود را کامل کند، هر چند کافران خوش نداشته باشند. 9:32
- صدقات (زکات) تنها برای: 1) فقرا، 2) مساکین، 3) کارگزاران جمع‌آوری آن، 4) کسانی که دل‌هایشان به اسلام گرایش یافته، 5) آزادی بردگان، 6) بدهکاران، 7) در راه الله (مجاهدان) و 8) در راه ماندگان است. 9:60
- هر کس با الله و پیامبرش (ﷺ) دشمنی و مخالفت ورزد، بی‌گمان آتش دوزخ برای اوست که در آن جاودانه خواهد ماند. این خواری بزرگی است. 9:63
- منافقان مرد و زن، همه از یک گروهند. الله را فراموش کردند، پس الله نیز آنان را فراموش کرد. 9:67
- به پاکی بکوشید. حرمت مسجد را پاس دارید. 9:108
- پیامبر و مؤمنان را نشاید که برای مشرکان، حتی اگر خویشاوند باشند، پس از آنکه برایشان روشن شد که آنان اهل دوزخند (به سبب آنکه در حال کفر مرده‌اند)، طلب آمرزش کنند. 9:113
- چه کسی ستمکارتر است از آن کس که بر الله دروغ بندد یا آیات او را تکذیب کند؟ بی‌گمان مجرمان رستگار نخواهند شد! 10:17
- آنان به جای الله چیزهایی را می‌پرستند که نه به آنان زیان می‌رساند و نه سودی می‌بخشد، و می‌گویند: "اینها شفیعان ما نزد الله هستند." بگو: "آیا الله را به چیزی آگاه می‌کنید که در آسمان‌ها و زمین نمی‌داند؟" او منزه و برتر است از آنچه شریک او می‌سازند! 10:18
- پاداش بدی، بدی‌ای مانند آن است. 10:27
- این است الله، پروردگار حقیقی شما. پس بعد از حق، جز گمراهی چیست؟ پس چگونه (از حق) برگردانده می‌شوید؟ 10:32
- بیشتر آنان جز از گمان پیروی نمی‌کنند. بی‌گمان گمان به هیچ وجه حق را بی‌نیاز نمی‌کند. 10:36
- هر آینه! الله به مردم هیچ ستمی نمی‌کند؛ بلکه مردم خود بر خویشتن ستم می‌کنند. 10:44
- بدانید که فضل الله بهتر است از هر آنچه انسان می‌تواند جمع یا ذخیره کند. 10:58
- از کسانی نباشید که آیات الله را تکذیب می‌کنند، که در این صورت از زیانکاران خواهید بود. 10:95
- اگر الله به تو گزندی رساند، جز او کسی آن را برطرف نمی‌کند؛ و اگر برای تو خیری بخواهد، هیچ کس فضل او را باز نمی‌گرداند، آن را به هر کس از بندگانش که بخواهد می‌رساند. 10:107
- هیچ جنبنده‌ای در زمین نیست، مگر آنکه روزی‌اش بر عهده الله است. و جایگاه و مدفن آن را می‌داند (در رحم، گور و غیره). 11:6
- اگر به انسان رحمتی از خود بچشانیم، سپس آن را از او بازگیریم، بی‌گمان نومید و ناسپاس می‌شود. 11:9
- هر که زندگی دنیا و زیور آن را بخواهد، پاداش کارهایشان را در همین دنیا به تمامی به آنان خواهیم داد و در آن چیزی از آنان کاسته نخواهد شد. 11:15
- ما به آنان ستم نکردیم، بلکه آنان خود بر خویشتن ستم کردند. پس معبودانی که به جای الله می‌خواندند، هنگامی که فرمان پروردگارت فرا رسید، هیچ سودی به حالشان نداشتند و جز هلاکت چیزی بر آنان نیفزودند. 11:101
- روزی که (عذاب) فرا رسد، هیچ کس جز به اذن او (الله) سخن نمی‌گوید. برخی از آنان شقی (بدبخت) و برخی سعید (خوشبخت) خواهند بود. 11:105
- اما کسانی که شقی (بدبخت) هستند، در آتشند، در آنجا ناله‌ای بلند و آهی کشیده دارند. 11:106
- تا آسمان‌ها و زمین باقی است، در آن جاودانه می‌مانند، مگر آنچه پروردگارت بخواهد. بی‌گمان پروردگارت هر چه بخواهد انجام می‌دهد. 11:107
- و کسانی که سعید (خوشبخت) هستند، در بهشتند و در آن جاودانه می‌مانند، تا آسمان‌ها و زمین باقی است، مگر آنچه پروردگارت بخواهد، عطایی بی‌پایان. 11:108
- به ستمگران مایل نشوید، که آتش به شما خواهد رسید، و برای شما غیر از الله هیچ دوستی نیست و سپس یاری نخواهید شد. 11:113
- در دو طرف روز و در ساعاتی از شب نماز برپا دارید (یعنی نمازهای پنج‌گانه). کارهای نیک، بدی‌ها (گناهان کوچک) را از میان می‌برند. 11:114
- غیب آسمان‌ها و زمین از آن الله است، و همه کارها به او بازگردانده می‌شود (برای تصمیم‌گیری). 11:123
- فرمان (یا حکم) تنها از آن الله است. او فرمان داده که جز او را نپرستید (توحید)، این است دین راست، ولی بیشتر مردم نمی‌دانند. 12:40
- هرگز از رحمت الله نومید مشوید. 12:87
- و بیشتر مردم هر چند به شدت آرزو کنی، ایمان نخواهند آورد. 12:103
- و بیشتر آنان به الله ایمان نمی‌آورند، مگر آنکه (به او) شرک می‌ورزند (یعنی مشرکند). 12:106
- این (قرآن) سخنی برساخته نیست، بلکه تصدیق کتاب‌های پیشین (تورات، انجیل و دیگر کتاب‌های آسمانی) و توضیحی مفصل برای هر چیزی و هدایت و رحمتی است برای مردمی که ایمان می‌آورند. 12:111
- الله روزی را برای هر که بخواهد، گشاده یا تنگ می‌گرداند. 13:26
- الله را با ذکر بسیار یاد کنید. کسانی که به خدا ایمان دارند، دل‌هایشان با یاد او آرام می‌گیرد. 13:28
- کسانی که ایمان آورده و کارهای شایسته کرده‌اند، شادکامی و آرامش دل دارند. 13:29
- کسانی که زندگی دنیا را بر آخرت ترجیح می‌دهند و (مردم را) از راه الله (اسلام) بازمی‌دارند و آن را کج می‌خواهند – آنان در گمراهی دوری هستند. 14:3
- در عبادت فروتنی و شکرگزاری پیشه کنید. 14:7
- مثل کسانی که به پروردگار خود کافر شدند، اعمالشان چون خاکستری است که در روزی طوفانی، باد شدیدی بر آن بوزد؛ از آنچه به دست آورده‌اند، هیچ بهره‌ای نمی‌برند. 14:18
- الله کسانی را که ایمان آورده‌اند، با گفتار استوار در زندگی دنیا (یعنی پیوسته تنها الله را می‌پرستند) و در آخرت استوار می‌دارد. 14:27
- گمان مبرید که الله از آنچه ستمگران (مشرکان، ستمکاران و غیره) انجام می‌دهند، غافل است؛ بلکه کیفر آنان را تا روزی که چشم‌ها از وحشت خیره می‌شود، به تأخیر می‌اندازد. 14:42
- تا الله هر کس را به آنچه به دست آورده، پاداش دهد. بی‌گمان الله سریع‌الحساب است. 14:51
- و هر آینه انسان را از گِلی خشک‌یده، از گل سیاه بدبو آفریدیم. 15:26
- و جن را پیش از آن، از آتشی سوزان (بی‌دود) آفریدیم. 15:27
- آن (دوزخ) هفت در دارد، و هر دری را گروهی (معین) از گناهکاران است. 15:44
- انسان را از نطفه‌ای (آمیخته از ترشحات جنسی مرد و زن) آفرید، و اینک همین (انسان) دشمنی آشکار شده است. 16:4
- و چهارپایان را برای شما آفرید؛ در آنها برای شما گرمی (لباس گرم) و سودهای بسیار است و از گوشت آنها می‌خورید. 16:5
- و (آفرید) اسبان و استران و خران را تا بر آنها سوار شوید و (نیز) زینت. و چیزهایی می‌آفریند که نمی‌دانید. 16:8
- اوست که از آسمان آبی (باران) فرود آورد؛ از آن می‌نوشید و از آن (گیاه) می‌روید که چهارپایان را در آن می‌چرانید. 16:10
- اوست که دریا را رام کرد تا از آن گوشت تازه (ماهی) بخورید و از آن زینتی (برای پوشیدن) بیرون آورید. 16:14
- و در زمین کوه‌هایی استوار نهاد تا با شما نلرزد، و جویبارها و راه‌ها (قرار داد) تا راه یابید. 16:15
- آیا آن کس که می‌آفریند، چون کسی است که نمی‌آفریند؟ آیا پند نمی‌گیرید؟ 16:17
- اگر نعمت‌های الله را بشمارید، هرگز نتوانید آنها را شماره کنید. 16:18
- الله آنچه را پنهان می‌دارید و آنچه را آشکار می‌کنید، می‌داند. 16:19
- آنهایی که (مشرکان) به جای الله می‌خوانند، چیزی نیافریده‌اند، بلکه خود آفریده شده‌اند. 16:20
- (آنها) مردگانی بی‌جانند و نمی‌دانند چه زمانی برانگیخته می‌شوند. 16:21
- سخن ما به چیزی هنگامی که آن را بخواهیم، این است که به آن گوییم: "باش!" پس می‌شود. 16:40
- آیا کسانی که نیرنگ‌های بد می‌کنند، ایمنند از اینکه الله آنان را در زمین فرو ببرد، یا عذاب از جایی که نمی‌دانند به سراغشان آید؟ 16:45
- هر نعمت و خوبی که دارید، از جانب الله است. آنگاه چون گزندی به شما رسد، فقط به درگاه او زاری می‌کنید. 16:53
- پس چون گزند را از شما برطرف ساخت، ناگهان گروهی از شما به پروردگار خود شرک می‌ورزند (با الله). 16:54
- و در چهارپایان برای شما عبرتی است. از آنچه در شکم‌هایشان است، میان سرگین و خون، شیری پاکیزه به شما می‌نوشانیم که برای نوشندگان گواراست. 16:66
- پس برای الله مثل‌ها مزنید (زیرا هیچ چیز مانند او نیست، و او به هیچ چیز نمی‌ماند). بی‌گمان الله می‌داند و شما نمی‌دانید. 16:74
- بدانید که خداوند به مردم گوش، چشم، عقل و احساسات داده است تا شکرگزار باشند. 16:78
- از آزمندی و بخل بپرهیزید. 16:97
- هنگامی که می‌خواهی قرآن بخوانی، از شیطان رانده شده به الله پناه ببر. 16:98
- بدانید که خطایی از روی نادانی، اگر شخص توبه کند و خود را اصلاح نماید، بخشیده می‌شود. 16:119
- (ای محمد ﷺ) با حکمت و پند نیکو به راه پروردگارت (اسلام) دعوت کن، و با آنان به بهترین شیوه مجادله کن. دعوت دیگران به راه خدا باید با حکمت و نیکی باشد. 16:125
- الله با کسانی است که از او پروا دارند (وظیفه خود را در برابر او به جای می‌آورند) و با کسانی که نیکوکارند. 16:128
- این قرآن به آنچه درست‌تر و عادلانه‌تر است، راه می‌نماید. 17:9
- هیچ کس بار گناه دیگری را به دوش نمی‌کشد. 17:15
- هر که آخرت را بخواهد و برای آن سعی و کوشش شایسته کند، در حالی که مؤمن است، پس اینان هستند که کوشششان مورد قدردانی و پاداش (از سوی الله) قرار خواهد گرفت. 17:19
- به پدر و مادر خود احترام بگذارید و با آنان به نیکی رفتار کنید. به پدر و مادر نیکوکار باشید. به پدر و مادر سخنی بی‌ادبانه مگویید. و پروردگارت فرمان داده که جز او را نپرستید و به پدر و مادر نیکی کنید. اگر یکی از آن دو یا هر دو، در کنار تو به سن پیری رسیدند، به آنان "اف" مگویید و بر سرشان فریاد مزنید، بلکه سخنی شایسته به آنان بگویید. 17:23
- و بال فروتنی خود را از روی مهربانی برای آنان فرود آر و بگو: "پروردگارا! به آنان رحمت آور، چنانکه مرا در کودکی پروردند." 17:24
- بی‌گمان اسراف‌کاران برادران شیطانند، و شیطان همواره نسبت به پروردگار خود ناسپاس است. 17:27
- اسراف مکنید. 17:29
- فرزندان خود را از ترس فقر مکشید. 17:31
- به زنا نزدیک نشوید. حرمت ازدواج را نگه دارید و از زنا بپرهیزید. 17:32
- هنگامی که پیمانه می‌کنید، پیمانه را کامل کنید و با ترازوی درست وزن کنید. این بهتر (و سودمندتر) و عاقبت آن نیکوتر است. 17:35
- (ای انسان) از آنچه به آن علم نداری، پیروی مکن (مثلاً کسی بگوید: "من دیدم"، در حالی که ندیده است، یا "من شنیدم"، در حالی که نشنیده است). 17:36
- فروتن باشید و تکبر نورزید. در زمین به نخوت و خودبزرگ‌بینی راه مرو. که تو هرگز زمین را نمی‌توانی شکافت و به بلندای کوه‌ها نمی‌توانی رسید. 17:37
- پروردگارت به شما داناتر است؛ اگر بخواهد، به شما رحم می‌کند، یا اگر بخواهد، شما را عذاب می‌دهد. 17:54
- هر که در این دنیا نابینا باشد (یعنی نشانه‌های الله را نبیند و به او ایمان نیاورد)، در آخرت نیز نابینا خواهد بود و از راه گم‌تر. 17:72
- اوقات مقرر نماز را نگه دارید. 17:78
- هر آینه در این قرآن، هر گونه مثل را برای مردم بیان کردیم، اما بیشتر مردم جز کفر را نمی‌پذیرند. 17:89
- ما در این قرآن برای مردم هر نوع مثالی آوردیم. اما انسان از همه چیز ستیزه‌جوتر است. 18:54
- کیفرشان دوزخ است؛ به سبب آنکه کفر ورزیدند و آیات من و پیامبرانم را به تمسخر و استهزا گرفتند. 18:106
- سزاوار (عظمت) الله نیست که فرزندی برای خود برگزیند (این اشاره به تهمت مسیحیان بر الله دارد که عیسی پسر خداست). او منزه است (و برتر از آنچه شریک او می‌سازند). 19:35
- با مردم به نرمی سخن گویید. 20:44
- در نیکی‌ها بر یکدیگر سبقت جویید. 21:90
- از سخن بیهوده دوری کنید. 23:3
- پاکدامنی خود را حفظ کنید. 23:5
- دل خود را از گرایش‌های گناه‌آلود حفظ کنید. 23:97
- از دیگران درگذرید و خطاهای آنان را ببخشید. 24:22
- به حریم خصوصی دیگران، به ویژه در خانه‌هایشان احترام بگذارید. حقوق همسایگان را ادا کنید. 24:27
- چشم‌های خود را (برای مردان و زنان) فرو بگیرید. پاکدامنی و عفت خود را حفظ کنید. 24:30
- در پوشش و رفتار، عفت و حیا را رعایت کنید. 24:31
- بدانید که خداوند به کسانی که او را عبادت می‌کنند و کار نیک انجام می‌دهند، امنیت و آرامش می‌بخشد. 24:55
- بدون اجازه، به اتاق خصوصی پدر و مادر وارد نشوید. 24:58
- فروتن و متواضع باشید. 25:63
- از شهادت دروغ و نیرنگ دوری کنید. 25:72
- برای پاداش آخرت بکوشید، اما کارهای دنیوی خود را نیز فرو نگذارید. 28:77
- با الله هیچ معبود دیگری را مخوانید. 28:88
- به همجنس‌گرایی نپردازید. 29:29
- در همه کوشش‌های خود به اوج برسید. 29:69
- نماز را برپا دارید و زکات دهید. 31:4
- امر به معروف و نهی از منکر کنید. 31:17
- در رفتار خود تکبر نورزید. و در گفتار بیهوده وقت را تلف نکنید. 31:18
- در راه رفتن و بلندی صدای خود میانه‌رو باشید. 31:19
- از پیامبر محمد الگو بگیرید. 33:21
- زنان نباید زینت و زیبایی خود را به نمایش بگذارند. 33:33
- در همه حال راست گویید. 33:70
- با تفکر، خرد و فهم را جستجو کنید. 38:29
- از اوامر قرآن پیروی کنید. 39:23
- خداوند همه گناهان را می‌بخشد، هنگامی که گناهکار توبه کند و به سوی او بازگردد. 39:53
- دعای خالصانه به الله کنید. 40:60
- بدی را به نیکی دفع کنید. 41:34
- کارها را با مشورت انجام دهید. 42:38
- صدای خود را بالاتر از صدای پیامبر مبرید. 49:2
- اسرار را حفظ کنید و از خیانت بپرهیزید. 49:6
- میان متخاصمان صلح برقرار کنید. در اختلافات به دنبال آشتی باشید. 49:9
- دیگران را مسخره نکنید. 49:11
- از گمان بد دوری کنید. از جاسوسی و غیبت بپرهیزید. از غیبت و تهمت دیگران خودداری کنید. از همه اشکال غیبت و تهمت دوری کنید. نگذارید تکبر شما را به ستم بکشاند. 49:12
- بدانید که تنها تقوا است که انسان را بزرگوار می‌کند. به تفاوت‌های میان مردم و فرهنگ‌ها احترام بگذارید. 49:13
- به مهمان احترام بگذارید. 51:26
- نسبت به وظایف خود در برابر الله هوشیار باشید. 51:56
- اموال خود را در راه خیر انفاق کنید. 57:7
- بدانید که در دین، رهبانیت (ترک ازدواج و لذت‌ها مانند راهبان و راهبه‌ها یا دیگران که تحت نذرهای دینی زندگی می‌کنند، یا ساختمان‌هایی که در آن ساکنند) وجود ندارد. 57:27
- مال و ثروت شما را از یاد الله غافل نکند. 58:11
- کسانی که علم دارند، خداوند آنان را درجات بالاتری می‌دهد. 58:11
- با غیرمسلمانان به نیکی و عدالت رفتار کنید. 60:8
- در عقاید و اعمال خود از نفاق بپرهیزید. 63:9
- از طمع و بخل دوری کنید. 64:16
- وحیانی را که به شما سپرده شده، حفظ کنید. 73:15
- روز قیامت را به یاد داشته باشید. 75:36
- به شکیبایی و مهربانی فرمان دهید. 90:17
- کسانی که نفس خود را پاک می‌کنند، رستگارند و کسانی که آن را آلوده می‌سازند، ناامید می‌شوند. 91:10
- نیازمندان را نادیده نگیرید و دور نکنید. 93:10
- دانش و فهم را جستجو کنید. قرآن بخوانید و در آن تدبر کنید. 96:1–5
- به اطعام فقرا تشویق کنید. 107:3
